import spriteData from './sprites.json';

/** A character made from a sprite sheet. Generated by `npm run sprites`. */
export interface SpriteSet {
  key: string; // texture key of the atlas
  image: string;
  atlas: string;
  displayScale: number; // atlas pixels -> game pixels
  anims: Record<string, number>; // animation name -> number of frames ("idle-0", "idle-1", ...)
}

export const SPRITES = spriteData as unknown as Record<string, SpriteSet>;
